'use strict';

const $ = selector => String(selector).startsWith('.') ? document.querySelector(selector) : document.getElementById(selector);
const NS = 'http://www.w3.org/2000/svg';
const palette = ['#2256a0','#c83c35','#228a54','#b56b16','#7446a8','#16818a','#9f3b70','#526b2c','#8d5946','#475f94','#d15b31','#367a68'];
const SHARED_COLOR = '#287757';
const PROJECT_VERSION = 5;
const LIMITS = {chains:200, narrators:250, text:10000, name:500, file:5_000_000};
const ar = value => Number(value).toLocaleString('ar-EG');
const uid = prefix => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,9)}`;
const normalize = value => String(value || '').trim().replace(/\s+/g, ' ').replace(/[إأآٱ]/g, 'ا').replace(/ى/g, 'ي');
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const cleanText = (value, max = LIMITS.text) => String(value ?? '').slice(0, max).trim();
const validColor = value => /^#[0-9a-f]{6}$/i.test(String(value || '')) ? String(value) : '';
const own = (object, key) => object && Object.prototype.hasOwnProperty.call(object, key) ? object[key] : undefined;
let db, project, graphData, guided = [], zoom = 1, saveTimer, highlightedChainId = null, layoutEdit = false;
let saveRevision = 0, savedRevision = 0, saveQueue = Promise.resolve(), saveState = 'saved';
let selected = {type:null, id:null};
let measureCanvas, measureContext;

function freshProject(name = 'مشروع جديد') {
  return {version:PROJECT_VERSION,id:uid('project'),name,title:'مشجّر حديث',matn:'',researcher:'',researchNotes:'',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),settings:{mergeExact:false,colorMode:'branch',showLegend:true,showMatn:true},chains:[],nodes:{},edges:{},projectNotes:[],positions:{}};
}

function demoProject() {
  const sample = freshProject('مثال تطبيقي');
  sample.title = 'طرق حديث مشتركة ومتفرعة';
  sample.matn = '«إنما الأعمال بالنيات» — متن تجريبي قابل للاستبدال';
  const rows = [['النبي ﷺ','ابن عمر','نافع','مالك','الشافعي'],['النبي ﷺ','ابن عمر','نافع','مالك','أحمد'],['أبو هريرة','الأعرج','أبو الزناد','مالك','الشافعي']];
  const identities = new Map();
  rows.forEach((names, index) => {
    const narrators = names.map(name => {
      const key = normalize(name);
      if (!identities.has(key)) identities.set(key, uid('n'));
      const identityId = identities.get(key);
      sample.nodes[identityId] ||= {name,color:'',note:'',manualTier:null};
      return {occurrenceId:uid('o'),name,identityId};
    });
    sample.chains.push({id:uid('chain'),label:`الطريق ${index+1}`,narrators,source:{book:index===0?'مثال توضيحي':'',volume:'',page:'',hadith:'',free:''},note:''});
  });
  return sample;
}

function openDB() { return new Promise((resolve,reject) => { const request=indexedDB.open('isnad-builder',1); request.onupgradeneeded=()=>request.result.createObjectStore('projects',{keyPath:'id'}); request.onsuccess=()=>{db=request.result;resolve();}; request.onerror=()=>reject(request.error); }); }
function dbAll() { return new Promise((resolve,reject) => { const request=db.transaction('projects').objectStore('projects').getAll(); request.onsuccess=()=>resolve(request.result); request.onerror=()=>reject(request.error); }); }
function dbPut(value) { return new Promise((resolve,reject) => { const request=db.transaction('projects','readwrite').objectStore('projects').put(structuredClone(value)); request.onsuccess=()=>resolve(); request.onerror=()=>reject(request.error); }); }
function dbDelete(id) { return new Promise((resolve,reject) => { const request=db.transaction('projects','readwrite').objectStore('projects').delete(id); request.onsuccess=()=>resolve(); request.onerror=()=>reject(request.error); }); }

function textEl(tag, attrs = {}, text = '') { const element=document.createElementNS(NS,tag); Object.entries(attrs).forEach(([key,value])=>element.setAttribute(key,value)); element.textContent=text; return element; }
function toast(message) { const element=$('toast'); element.textContent=message; element.classList.add('show'); clearTimeout(element._timer); element._timer=setTimeout(()=>element.classList.remove('show'),2400); }
function download(name,blob) { const url=URL.createObjectURL(blob),anchor=document.createElement('a'); anchor.href=url; anchor.download=name; document.body.append(anchor); anchor.click(); anchor.remove(); setTimeout(()=>URL.revokeObjectURL(url),2500); }
function nodeMeta(id,name='') { return project.nodes[id] || (project.nodes[id]={name,color:'',note:'',manualTier:null}); }
function edgeKey(from,to) { return `${from}→${to}`; }
function isProphetName(name) { const value=normalize(name).replace(/[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]/g,'').replace(/ﷺ|صلى الله عليه وسلم|عليه الصلاة والسلام/g,'').replace(/[()،,:؛.\-–—]/g,' ').replace(/\s+/g,' ').trim();return /^(النبي|رسول الله)(?:\s|$)/.test(value); }
function stableIndex(key) { let hash=2166136261; for (const char of String(key)) { hash^=char.codePointAt(0); hash=Math.imul(hash,16777619); } return Math.abs(hash>>>0)%palette.length; }
function chainColor(chain) { return palette[stableIndex(chain.id)]; }

function addNames(names,source='',note='') {
  const seen=new Map();
  const narrators=names.map(raw=>{ const name=cleanText(raw,LIMITS.name),key=normalize(name); let identityId; if(project.settings.mergeExact) identityId=Object.entries(project.nodes).find(([,meta])=>normalize(meta.name)===key)?.[0]; if(!identityId&&seen.has(key)) identityId=seen.get(key); if(!identityId){identityId=uid('n');nodeMeta(identityId,name);} seen.set(key,identityId); return {occurrenceId:uid('o'),name,identityId}; });
  project.chains.push({id:uid('chain'),label:`الطريق ${project.chains.length+1}`,narrators,source:{book:'',volume:'',page:'',hadith:'',free:cleanText(source)},note:cleanText(note)});
}
function parseQuick() { return $('quickInput').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>line.split(/[,،]/).map(name=>name.trim()).filter(Boolean)); }

function buildGraph() {
  const nodes=new Map(),edges=new Map();
  for (const [chainIndex,chain] of project.chains.entries()) {
    if(chain.narrators.length<2) continue;
    chain.narrators.forEach((occurrence,index)=>{ const meta=nodeMeta(occurrence.identityId,occurrence.name); if(!meta.name) meta.name=occurrence.name; if(!nodes.has(occurrence.identityId)) nodes.set(occurrence.identityId,{id:occurrence.identityId,name:meta.name,paths:[],occurrences:[]}); const node=nodes.get(occurrence.identityId); if(!node.paths.includes(chainIndex)) node.paths.push(chainIndex); node.occurrences.push({chainId:chain.id,chainIndex,occurrenceId:occurrence.occurrenceId,name:occurrence.name}); if(index>0){ const from=chain.narrators[index-1].identityId,to=occurrence.identityId,key=edgeKey(from,to); if(from===to) throw Error(`الهوية «${meta.name}» مكررة متتابعة في الطريق ${chainIndex+1}`); if(!edges.has(key)) edges.set(key,{id:key,from,to,paths:[]}); if(!edges.get(key).paths.includes(chainIndex)) edges.get(key).paths.push(chainIndex); } });
  }
  const graph={nodes:[...nodes.values()],edges:[...edges.values()]}; layoutGraph(graph); assignBranchColors(graph); return graph;
}

function textWidth(text,font='19px Amiri, serif'){measureCanvas||=(document.createElement('canvas'));measureContext||=measureCanvas.getContext('2d');measureContext.font=font;measureContext.direction='rtl';return measureContext.measureText(String(text||'')).width;}
function measureNarrator(text,maxLineWidth=420){const value=String(text||'').trim(),words=value.split(/\s+/).filter(Boolean);if(!words.length)return{lines:[''],width:90};if(textWidth(value)<=maxLineWidth)return{lines:[value],width:textWidth(value)};const lines=[];let current='';for(const word of words){const candidate=current?`${current} ${word}`:word;if(current&&textWidth(candidate)>maxLineWidth){lines.push(current);current=word;}else current=candidate;}if(current)lines.push(current);return{lines,width:Math.max(...lines.map(line=>textWidth(line)))};}
function wrapText(text,max=70) { const result=[]; String(text||'').split(/\r?\n/).forEach(paragraph=>{const words=paragraph.trim().split(/\s+/).filter(Boolean);if(!words.length){result.push('');return;}let line='';words.forEach(word=>{if((`${line} ${word}`).trim().length>max&&line){result.push(line);line=word;}else line=(`${line} ${word}`).trim();});if(line)result.push(line);});return result; }
function average(values) { return values.length?values.reduce((sum,value)=>sum+value,0)/values.length:0; }
function packLevel(list,desired,gap=46){if(!list.length)return;let cursor=-Infinity;for(const node of list){const target=desired(node);node.x=Math.max(target,cursor+node.w/2);cursor=node.x+node.w/2+gap;}const shift=average(list.map(desired))-average(list.map(node=>node.x));list.forEach(node=>node.x+=shift);}

function layoutGraph(graph) {
  const indegree=new Map(graph.nodes.map(node=>[node.id,0])),outgoing=new Map(graph.nodes.map(node=>[node.id,[]])),parents=new Map(graph.nodes.map(node=>[node.id,[]]));
  graph.edges.forEach(edge=>{outgoing.get(edge.from).push(edge.to);parents.get(edge.to).push(edge.from);indegree.set(edge.to,indegree.get(edge.to)+1);});
  const prophetIds=new Set(graph.nodes.filter(node=>isProphetName(nodeMeta(node.id,node.name).name)).map(node=>node.id));
  for(const edge of graph.edges) if(prophetIds.has(edge.to)) throw Error('إذا ذُكر النبي ﷺ فيجب أن يكون أول اسم في الإسناد المدخل.');
  const queue=[...indegree].filter(([,count])=>count===0).map(([id])=>id),working=new Map(indegree),topological=[];
  while(queue.length){const id=queue.shift();topological.push(id);for(const to of outgoing.get(id)){working.set(to,working.get(to)-1);if(working.get(to)===0)queue.push(to);}}
  if(topological.length!==graph.nodes.length) throw Error('ينتج عن الهويات الحالية مسار دائري. افصل الهوية الملتبسة أو صحّح ترتيب السند.');
  const hasProphet=prophetIds.size>0;
  const depth=new Map(graph.nodes.map(node=>{const meta=nodeMeta(node.id,node.name),manual=Number.isInteger(meta.manualTier)?Math.max(0,meta.manualTier):0,rootBase=indegree.get(node.id)===0&&hasProphet&&!prophetIds.has(node.id)?1:0;return[node.id,prophetIds.has(node.id)?0:Math.max(rootBase,manual)];}));
  for(const id of topological){if(prophetIds.has(id))depth.set(id,0);const meta=nodeMeta(id);if(!prophetIds.has(id)&&Number.isInteger(meta.manualTier))depth.set(id,Math.max(depth.get(id),meta.manualTier));for(const to of outgoing.get(id))depth.set(to,Math.max(depth.get(to),depth.get(id)+1));}
  const levels=new Map(); graph.nodes.forEach(node=>{const measured=measureNarrator(nodeMeta(node.id,node.name).name);node.lines=measured.lines;node.w=Math.max(132,Math.ceil(measured.width)+44);node.h=Math.max(56,30+node.lines.length*24);node.level=depth.get(node.id);if(!levels.has(node.level))levels.set(node.level,[]);levels.get(node.level).push(node);});
  const nodeById=new Map(graph.nodes.map(node=>[node.id,node])),children=new Map(graph.nodes.map(node=>[node.id,[]]));graph.edges.forEach(edge=>children.get(edge.from).push(edge.to));const ordered=[...levels.keys()].sort((a,b)=>a-b);
  for(const list of levels.values()){list.sort((a,b)=>nodeMeta(a.id).name.localeCompare(nodeMeta(b.id).name,'ar'));const total=list.reduce((sum,node)=>sum+node.w,0)+Math.max(0,list.length-1)*46;let cursor=-total/2;list.forEach(node=>{node.x=cursor+node.w/2;cursor+=node.w+46;});}
  for(let pass=0;pass<8;pass++){for(const level of ordered.slice(1)){const list=levels.get(level);list.sort((a,b)=>{const av=average(parents.get(a.id).map(id=>nodeById.get(id)?.x).filter(Number.isFinite)),bv=average(parents.get(b.id).map(id=>nodeById.get(id)?.x).filter(Number.isFinite));return(av-bv)||a.x-b.x;});packLevel(list,node=>{const values=parents.get(node.id).map(id=>nodeById.get(id)?.x).filter(Number.isFinite);return values.length?average(values):node.x;});}for(const level of ordered.slice(0,-1).reverse()){const list=levels.get(level);list.sort((a,b)=>{const av=average(children.get(a.id).map(id=>nodeById.get(id)?.x).filter(Number.isFinite)),bv=average(children.get(b.id).map(id=>nodeById.get(id)?.x).filter(Number.isFinite));return(av-bv)||a.x-b.x;});packLevel(list,node=>{const values=children.get(node.id).map(id=>nodeById.get(id)?.x).filter(Number.isFinite);return values.length?average(values):node.x;});}}
  const neighbors=new Map(graph.nodes.map(node=>[node.id,new Set()]));graph.edges.forEach(edge=>{neighbors.get(edge.from).add(edge.to);neighbors.get(edge.to).add(edge.from);});const visited=new Set(),components=[];for(const node of graph.nodes){if(visited.has(node.id))continue;const component=[],pending=[node.id];visited.add(node.id);while(pending.length){const id=pending.pop(),item=nodeById.get(id);component.push(item);for(const next of neighbors.get(id))if(!visited.has(next)){visited.add(next);pending.push(next);}}components.push(component);}components.sort((a,b)=>Math.min(...a.map(node=>node.x-node.w/2))-Math.min(...b.map(node=>node.x-node.w/2)));let componentCursor=0;for(const component of components){const min=Math.min(...component.map(node=>node.x-node.w/2)),max=Math.max(...component.map(node=>node.x+node.w/2)),offset=componentCursor-min;component.forEach(node=>node.x+=offset);componentCursor+=max-min+110;}
  const autoMin=Math.min(0,...graph.nodes.map(node=>node.x-node.w/2)),autoMax=Math.max(0,...graph.nodes.map(node=>node.x+node.w/2)),shiftX=90-autoMin,width=Math.max(760,autoMax-autoMin+180);graph.nodes.forEach(node=>node.x+=shiftX);
  const matnLines=project.settings.showMatn&&project.matn?wrapText(project.matn,70):[],matnHeight=matnLines.length?matnLines.length*30+58:0,levelY=new Map();let previousLevel=null,previousHeight=0,currentY=matnHeight+52;
  for(const level of ordered){const height=Math.max(...levels.get(level).map(node=>node.h));currentY+=previousLevel===null?height/2:(level-previousLevel)*78+previousHeight/2+height/2;levelY.set(level,currentY);previousLevel=level;previousHeight=height;}
  for(const node of graph.nodes){node.autoY=levelY.get(node.level);const saved=project.positions[node.id];node.x=saved?.x??node.x;node.y=Math.max(node.autoY-18,Math.min(node.autoY+18,saved?.y??node.autoY));}
  graph.width=width;graph.height=Math.max(390,...graph.nodes.map(node=>node.y+node.h/2+80));graph.matnLines=matnLines;graph.matnHeight=matnHeight;
}

function assignBranchColors(graph) {
  const incoming=new Map(graph.nodes.map(node=>[node.id,[]])),outgoing=new Map(graph.nodes.map(node=>[node.id,[]]));graph.edges.forEach(edge=>{incoming.get(edge.to).push(edge);outgoing.get(edge.from).push(edge);});
  for(const edge of graph.edges){if(edge.paths.length>1){edge.branchColor=SHARED_COLOR;continue;}const route=edge.paths[0];let anchor=edge;const seen=new Set();while(!seen.has(anchor.id)){seen.add(anchor.id);const previous=incoming.get(anchor.from)||[],departures=outgoing.get(anchor.from)||[];if(previous.length!==1||departures.length!==1)break;const candidate=previous[0];if(candidate.paths.length!==1||candidate.paths[0]!==route)break;anchor=candidate;}edge.branchColor=palette[stableIndex(anchor.id)];}
}
function edgeColors(edge) { const manual=project.edges[edge.id]?.color;if(manual)return[manual];if(project.settings.colorMode==='chain')return edge.paths.map(index=>chainColor(project.chains[index]));return[edge.branchColor||SHARED_COLOR]; }
function chainIndicator(chain,index) { if(project.settings.colorMode==='chain')return chainColor(chain);const first=graphData?.edges.find(edge=>edge.paths.includes(index)&&edge.paths.length===1);return first?.branchColor||SHARED_COLOR; }
function appendSvgLines(parent,lines,attrs,lineHeight=28){const text=textEl('text',attrs);lines.forEach((line,index)=>text.append(textEl('tspan',{x:attrs.x,dy:index===0?0:lineHeight},line||' ')));parent.append(text);return text;}

function draw(shouldSave=true) {
  try{
    graphData=buildGraph();reconcileSelection();const svg=$('graph');svg.replaceChildren();$('emptyState').classList.toggle('hidden',graphData.nodes.length>0);
    if(!graphData.nodes.length){svg.removeAttribute('viewBox');renderSide();renderFootnotes();if(shouldSave)scheduleSave();return;}
    let minX=0,maxX=graphData.width,minY=0,maxY=graphData.height;graphData.nodes.forEach(node=>{minX=Math.min(minX,node.x-node.w/2-8);maxX=Math.max(maxX,node.x+node.w/2+8);minY=Math.min(minY,node.y-node.h/2-8);maxY=Math.max(maxY,node.y+node.h/2+8);});const padding=50,width=maxX-minX+padding*2,height=maxY-minY+padding*2;
    svg.setAttribute('viewBox',`${minX-padding} ${minY-padding} ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);svg.append(textEl('rect',{class:'export-background',x:minX-padding,y:minY-padding,width,height,fill:'#fcfdfb'}));
    if(graphData.matnLines.length){const group=textEl('g',{class:'matn-layer'});appendSvgLines(group,graphData.matnLines,{x:(minX+maxX)/2,y:32,'text-anchor':'middle','font-family':'Amiri,serif','font-size':24,'font-weight':'700',fill:'#263e35',direction:'rtl'},30);group.append(textEl('line',{x1:(minX+maxX)/2-170,x2:(minX+maxX)/2+170,y1:graphData.matnHeight-18,y2:graphData.matnHeight-18,stroke:'#d7c28f'}));svg.append(group);}
    const layer=textEl('g',{class:'diagram-layer'}),byId=new Map(graphData.nodes.map(node=>[node.id,node]));
    for(const edge of graphData.edges){const from=byId.get(edge.from),to=byId.get(edge.to);if(!from||!to)continue;const d=edgePath(from,to),colors=edgeColors(edge);colors.forEach((color,index)=>{const classes=['edge','visible'];if(selected.type==='edge'&&selected.id===edge.id)classes.push('selected');if(highlightedChainId)classes.push(edge.paths.some(i=>project.chains[i].id===highlightedChainId)?'route-focus':'route-dim');layer.append(textEl('path',{class:classes.join(' '),'data-edge-id':edge.id,d,stroke:color,'stroke-width':colors.length>1?3:4,transform:colors.length>1?`translate(${(index-(colors.length-1)/2)*5} 0)`:''}));});const hit=textEl('path',{class:'edge-hit','data-id':edge.id,'data-edge-id':edge.id,d,tabindex:'0',role:'button','aria-label':`وصلة ${nodeMeta(edge.from).name} إلى ${nodeMeta(edge.to).name}`});hit.addEventListener('click',event=>{event.stopPropagation();selectEdge(edge.id);});hit.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectEdge(edge.id);}});layer.append(hit);if(project.edges[edge.id]?.note){const middle=curveMid(from,to);layer.append(textEl('circle',{cx:middle.x,cy:middle.y,r:9,class:'footnote-badge'}));layer.append(textEl('text',{x:middle.x,y:middle.y+4,'text-anchor':'middle','font-size':10,fill:'#fff'},footnoteNumber('edge',edge.id)));}}
    for(const node of graphData.nodes){const meta=nodeMeta(node.id,node.name),prophet=isProphetName(meta.name),classes=['node'];if(selected.type==='node'&&selected.id===node.id)classes.push('selected');if(highlightedChainId)classes.push(node.paths.some(i=>project.chains[i].id===highlightedChainId)?'route-focus':'route-dim');const group=textEl('g',{class:classes.join(' '),'data-id':node.id,transform:`translate(${node.x} ${node.y})`,tabindex:'0',role:'button','aria-label':`الراوي ${meta.name}`});group.append(textEl('rect',{x:-node.w/2,y:-node.h/2,width:node.w,height:node.h,rx:9,fill:meta.color||(prophet?'#4a2b8a':'#ffffff'),stroke:prophet?'#4a2b8a':'#94a99e','stroke-width':1.4}));const startY=-((node.lines.length-1)*24)/2+7;node.lines.forEach((line,index)=>group.append(textEl('text',{x:0,y:startY+index*24,'text-anchor':'middle','font-size':19,'font-family':'Amiri,serif',fill:prophet&&!meta.color?'#fff':'#1c342b'},line)));if(meta.note){group.append(textEl('circle',{cx:-node.w/2+11,cy:-node.h/2+11,r:9,class:'footnote-badge'}));group.append(textEl('text',{x:-node.w/2+11,y:-node.h/2+15,'text-anchor':'middle','font-size':10,fill:'#fff'},footnoteNumber('node',node.id)));}group.addEventListener('click',event=>{event.stopPropagation();if(!group._dragged)selectNode(node.id);group._dragged=false;});group.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectNode(node.id);}});dragNode(group,node,svg);layer.append(group);}
    svg.append(layer);applyZoom();renderSide();renderFootnotes();if(shouldSave)scheduleSave();
  }catch(error){toast(error.message);console.error(error);}
}

function curveMid(from,to){return{x:(from.x+to.x)/2,y:(from.y+to.y)/2};}
function edgePath(from,to){return`M ${from.x} ${from.y+from.h/2} C ${from.x} ${from.y+from.h/2+45}, ${to.x} ${to.y-to.h/2-45}, ${to.x} ${to.y-to.h/2}`;}
function updateConnectedEdges(nodeId){const byId=new Map(graphData.nodes.map(item=>[item.id,item]));graphData.edges.filter(edge=>edge.from===nodeId||edge.to===nodeId).forEach(edge=>{const from=byId.get(edge.from),to=byId.get(edge.to),d=edgePath(from,to);$('graph').querySelectorAll(`[data-edge-id="${CSS.escape(edge.id)}"]`).forEach(path=>path.setAttribute('d',d));});}
function dragNode(group,node,svg){group.addEventListener('pointerdown',event=>{if(!layoutEdit||event.button!==0)return;event.preventDefault();event.stopPropagation();const rect=svg.getBoundingClientRect(),viewBox=svg.viewBox.baseVal,startX=event.clientX,startY=event.clientY,originalX=node.x,originalY=node.y,tierCenter=node.autoY;let moved=false,finished=false;group.classList.add('dragging');group.setPointerCapture(event.pointerId);const move=current=>{const dx=current.clientX-startX,dy=current.clientY-startY;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;node.x=Math.max(-500,Math.min(graphData.width+500,originalX+dx*viewBox.width/rect.width));const proposedY=originalY+dy*viewBox.height/rect.height;node.y=Math.max(tierCenter-18,Math.min(tierCenter+18,proposedY));project.positions[node.id]={x:node.x,y:node.y};group.setAttribute('transform',`translate(${node.x} ${node.y})`);updateConnectedEdges(node.id);};const finish=()=>{if(finished)return;finished=true;group.classList.remove('dragging');group.removeEventListener('pointermove',move);group.removeEventListener('pointerup',finish);group.removeEventListener('pointercancel',finish);group.removeEventListener('lostpointercapture',finish);group._dragged=moved;if(moved)draw();};group.addEventListener('pointermove',move);group.addEventListener('pointerup',finish);group.addEventListener('pointercancel',finish);group.addEventListener('lostpointercapture',finish);});}

function footnoteItems(){const items=[];project.projectNotes.forEach(note=>items.push({type:'project',id:note.id,label:'حاشية عامة',text:note.text}));graphData?.nodes.forEach(node=>{const meta=nodeMeta(node.id,node.name);if(meta.note)items.push({type:'node',id:node.id,label:meta.name,text:meta.note});});graphData?.edges.forEach(edge=>{const meta=project.edges[edge.id];if(meta?.note)items.push({type:'edge',id:edge.id,label:`${nodeMeta(edge.from).name} ← ${nodeMeta(edge.to).name}`,text:meta.note});});return items;}
function footnoteNumber(type,id){const index=footnoteItems().findIndex(item=>item.type===type&&item.id===id);return index<0?'':ar(index+1);}
function renderFootnotes(){const notes=footnoteItems(),sources=project.chains.filter(chain=>Object.values(chain.source||{}).some(Boolean));$('footnoteCount').textContent=ar(notes.length+sources.length);let html=sources.map((chain,index)=>`<div class="footnote-item"><b class="note-num">م</b><span><strong>${esc(chain.label||`الطريق ${index+1}`)}:</strong> ${esc(sourceText(chain.source))}${chain.note?` — ${esc(chain.note)}`:''}</span></div>`).join('');html+=notes.map((note,index)=>`<div class="footnote-item"><b class="note-num">${ar(index+1)}</b><span><strong>${esc(note.label)}:</strong> ${esc(note.text)}</span></div>`).join('');$('footnotes').innerHTML=html||'<p class="field-help">لا توجد مصادر أو حواشٍ بعد.</p>';}
function sourceText(source={}){return[source.book,source.volume&&`ج ${source.volume}`,source.page&&`ص ${source.page}`,source.hadith&&`رقم ${source.hadith}`,source.free].filter(Boolean).join('، ');}
function renderSide(){renderChains();renderNotes();renderKnown();$('chainCount').textContent=ar(project.chains.length);$('stats').textContent=`${ar(project.chains.length)} أسانيد • ${ar(graphData?.nodes.length||0)} هويات • ${ar(graphData?.edges.length||0)} وصلات`;}

  function renderChains(){const root=$('chainList'),openIds=new Set([...root.querySelectorAll('.chain-card[open]')].map(card=>card.dataset.id));root.replaceChildren();project.chains.forEach((chain,index)=>{const details=document.createElement('details');details.className=`chain-card ${highlightedChainId===chain.id?'highlighted':''}`;details.dataset.id=chain.id;details.open=openIds.has(chain.id);const source=sourceText(chain.source);details.innerHTML=`<summary><div class="chain-title"><i class="chain-swatch" style="background:${chainIndicator(chain,index)}"></i><span class="chain-path">${esc(chain.narrators.map(item=>item.name).join(' ← '))}</span><span>${ar(index+1)}</span></div>${source?`<small class="chain-source">${esc(source)}</small>`:''}</summary><div class="chain-body"><label>اسم الطريق<input data-field="label" value="${esc(chain.label||'')}"></label><label>نص الإسناد<textarea data-field="path" rows="2">${esc(chain.narrators.map(item=>item.name).join('، '))}</textarea></label><div class="chain-meta-grid"><label>الكتاب<input data-source="book" value="${esc(chain.source?.book||'')}"></label><label>الجزء<input data-source="volume" value="${esc(chain.source?.volume||'')}"></label><label>الصفحة<input data-source="page" value="${esc(chain.source?.page||'')}"></label><label>رقم الحديث<input data-source="hadith" value="${esc(chain.source?.hadith||'')}"></label></div><label>مرجع حر<input data-source="free" value="${esc(chain.source?.free||'')}"></label><label>ملاحظة الطريق<textarea data-field="note" rows="2">${esc(chain.note||'')}</textarea></label><div class="chain-actions"><button class="text-button" data-highlight>${highlightedChainId===chain.id?'إلغاء التمييز':'تمييز الطريق'}</button><button class="text-button" data-move="up">رفع</button><button class="text-button" data-duplicate>نسخ</button><button class="text-button danger-text" data-delete>حذف</button></div></div>`;details.querySelectorAll('input,textarea').forEach(input=>input.addEventListener('change',()=>updateChainFromCard(chain,input)));details.querySelector('[data-highlight]').onclick=event=>{event.preventDefault();setChainHighlight(chain.id);};details.querySelector('[data-delete]').onclick=()=>{project.chains=project.chains.filter(item=>item.id!==chain.id);if(highlightedChainId===chain.id)highlightedChainId=null;prune();draw();};details.querySelector('[data-duplicate]').onclick=()=>{const copy=structuredClone(chain);copy.id=uid('chain');copy.label=`${copy.label} — نسخة`;copy.narrators.forEach(item=>item.occurrenceId=uid('o'));project.chains.splice(index+1,0,copy);draw();};details.querySelector('[data-move]').onclick=()=>{if(index>0){[project.chains[index-1],project.chains[index]]=[project.chains[index],project.chains[index-1]];draw();}};root.append(details);});}
function setChainHighlight(id){highlightedChainId=highlightedChainId===id?null:id;draw(false);}
function updateChainFromCard(chain,input){if(input.dataset.source){chain.source[input.dataset.source]=cleanText(input.value);draw();return;}if(input.dataset.field!=='path'){chain[input.dataset.field]=cleanText(input.value);draw();return;}const names=input.value.split(/[,،]/).map(value=>value.trim()).filter(Boolean);if(names.length<2){toast('يحتاج الإسناد إلى اسمين على الأقل');input.value=chain.narrators.map(item=>item.name).join('، ');return;}if(names.length>LIMITS.narrators)return toast('الإسناد أطول من الحد المدعوم.');const backup=structuredClone(project),old=chain.narrators;try{chain.narrators=names.map((name,index)=>old[index]&&normalize(old[index].name)===normalize(name)?{...old[index],name:cleanText(name,LIMITS.name)}:{occurrenceId:uid('o'),name:cleanText(name,LIMITS.name),identityId:findIdentityForInput(name)});assertAcyclic(project);prune();draw();}catch(error){project=backup;toast(error.message);draw();}}
function findIdentityForInput(name){if(project.settings.mergeExact){const found=Object.entries(project.nodes).find(([,meta])=>normalize(meta.name)===normalize(name));if(found)return found[0];}const id=uid('n');nodeMeta(id,cleanText(name,LIMITS.name));return id;}
function prune(){const usedNodes=new Set(project.chains.flatMap(chain=>chain.narrators.map(item=>item.identityId))),usedEdges=new Set();project.chains.forEach(chain=>{for(let index=1;index<chain.narrators.length;index++)usedEdges.add(edgeKey(chain.narrators[index-1].identityId,chain.narrators[index].identityId));});Object.keys(project.nodes).forEach(id=>{if(!usedNodes.has(id)){delete project.nodes[id];delete project.positions[id];}});Object.keys(project.edges).forEach(key=>{if(!usedEdges.has(key))delete project.edges[key];});}
function renderNotes(){$('projectNotes').innerHTML=project.projectNotes.map((note,index)=>`<div class="note-item"><b class="note-num">${ar(index+1)}</b><span>${esc(note.text)}</span><button class="text-button danger-text" data-id="${esc(note.id)}">حذف</button></div>`).join('')||'<p class="field-help">لا توجد حواشٍ عامة.</p>';$('projectNotes').querySelectorAll('button').forEach(button=>button.onclick=()=>{project.projectNotes=project.projectNotes.filter(note=>note.id!==button.dataset.id);draw();});}
