function reconcileSelection(){if(selected.type==='node'&&!graphData.nodes.some(node=>node.id===selected.id))selected={type:null,id:null};if(selected.type==='edge'&&!graphData.edges.some(edge=>edge.id===selected.id))selected={type:null,id:null};if(!selected.type){$('.inspector-empty')?.classList.remove('hidden');$('nodeInspector')?.classList.add('hidden');$('edgeInspector')?.classList.add('hidden');}}
