function applyProject(){project=migrateProject(project);resetSaveTracking();$('diagramTitle').value=project.title;$('matnText').value=project.matn;$('researcherName').value=project.researcher||'';$('researcherNotes').value=project.researchNotes||'';$('mergeExact').checked=!!project.settings.mergeExact;document.querySelector(`input[name=colorMode][value="${project.settings.colorMode}"]`).checked=true;$('showLegend').checked=project.settings.showLegend!==false;$('showMatn').checked=project.settings.showMatn!==false;selected={type:null,id:null};highlightedChainId=null;$('.inspector-empty').classList.remove('hidden');$('nodeInspector').classList.add('hidden');$('edgeInspector').classList.add('hidden');renderProjectMeta();draw(false);}

