function bind(){
  document.querySelectorAll('.tab').forEach(button=>button.onclick=()=>{document.querySelectorAll('.tab').forEach(item=>{item.classList.remove('active');item.setAttribute('aria-selected','false');});document.querySelectorAll('.tab-panel').forEach(panel=>panel.classList.add('hidden'));button.classList.add('active');button.setAttribute('aria-selected','true');$(`tab-${button.dataset.tab}`).classList.remove('hidden');});
  $('addQuick').onclick=()=>{const rows=parseQuick();if(!rows.length)return toast('اكتب إسنادًا واحدًا على الأقل.');if(rows.some(row=>row.length<2))return toast('كل إسناد يحتاج إلى اسمين على الأقل.');if(rows.some(row=>row.length>LIMITS.narrators)||project.chains.length+rows.length>LIMITS.chains)return toast('تجاوز الإدخال الحد الآمن للمشروع.');const backup=structuredClone(project);try{rows.forEach(row=>addNames(row));assertAcyclic(project);$('quickInput').value='';draw();}catch(error){project=backup;toast(error.message);draw();}};$('clearQuick').onclick=()=>$('quickInput').value='';
  $('guidedName').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();const value=event.target.value.trim();if(value){guided.push(cleanText(value,LIMITS.name));event.target.value='';renderGuided();}}};$('finishGuided').onclick=()=>{if(guided.length<2)return toast('أدخل اسمين على الأقل.');const backup=structuredClone(project);try{addNames(guided,$('guidedSource').value,$('guidedNote').value);assertAcyclic(project);guided=[];$('guidedSource').value=$('guidedNote').value='';renderGuided();draw();}catch(error){project=backup;toast(error.message);draw();}};$('undoGuided').onclick=()=>{guided.pop();renderGuided();};
  $('saveProject').onclick=()=>saveProject().catch(error=>{console.error(error);toast('تعذر الحفظ المحلي.');});$('projectSelect').onchange=async event=>{const previous=project.id,target=event.target.value;try{await saveProject(false);const raw=(await dbAll()).find(item=>item.id===target);if(!raw)throw Error('المشروع المطلوب غير موجود.');project=migrateProject(raw);applyProject();}catch(error){event.target.value=previous;setSaveStatus('failed');toast('لم يُفتح المشروع الآخر لأن حفظ التغييرات الحالية تعذّر.');console.error(error);}};$('projectMenuButton').onclick=()=>{const menu=$('projectMenu');menu.classList.toggle('hidden');$('projectMenuButton').setAttribute('aria-expanded',String(!menu.classList.contains('hidden')));};$('projectMenu').onclick=event=>projectAction(event.target.dataset.action).catch(error=>{console.error(error);setSaveStatus('failed');toast('تعذّر إتمام العملية قبل حفظ المشروع.');});$('jsonFile').onchange=importProject;
  $('mergeExact').onchange=event=>{project.settings.mergeExact=event.target.checked;scheduleSave();};document.querySelectorAll('input[name=colorMode]').forEach(input=>input.onchange=event=>{project.settings.colorMode=event.target.value;draw();});$('diagramTitle').oninput=event=>{project.title=cleanText(event.target.value,300);scheduleSave();};$('matnText').oninput=event=>{project.matn=cleanText(event.target.value,LIMITS.text);scheduleSave();};$('matnText').onchange=()=>{project.positions={};draw();};$('researcherName').oninput=event=>{project.researcher=cleanText(event.target.value,LIMITS.name);renderProjectMeta();scheduleSave();};$('researcherNotes').oninput=event=>{project.researchNotes=cleanText(event.target.value,LIMITS.text);scheduleSave();};$('showMatn').onchange=event=>{project.settings.showMatn=event.target.checked;project.positions={};draw();};$('showLegend').onchange=event=>{project.settings.showLegend=event.target.checked;draw();};$('resetLayout').onclick=()=>{project.positions={};draw();fitDiagram();toast('أُعيد ترتيب المشجّر تلقائيًا.');};$('editLayout').onclick=()=>{layoutEdit=!layoutEdit;$('editLayout').classList.toggle('active',layoutEdit);$('editLayout').setAttribute('aria-pressed',String(layoutEdit));$('diagramViewport').classList.toggle('layout-edit',layoutEdit);toast(layoutEdit?'وضع التحريك اليدوي مفعّل.':'عاد وضع التحديد العادي.');};
  $('addProjectNote').onclick=()=>{const text=cleanText($('projectNoteInput').value);if(text){project.projectNotes.push({id:uid('note'),text});$('projectNoteInput').value='';draw();}};
  $('applyNode').onclick=()=>{const meta=nodeMeta(selected.id),name=cleanText($('nodeName').value,LIMITS.name)||meta.name;meta.name=name;meta.color=validColor($('nodeColor').value);meta.note=cleanText($('nodeNote').value);meta.manualTier=isProphetName(name)||$('nodeTier').value===''?null:Math.max(1,Math.min(50,Number($('nodeTier').value)));project.chains.flatMap(chain=>chain.narrators).filter(item=>item.identityId===selected.id).forEach(item=>item.name=name);project.positions={};draw();selectNode(selected.id,true);};$('mergeNode').onclick=mergeSelected;$('splitNode').onclick=splitSelected;$('applyEdge').onclick=()=>{project.edges[selected.id]={...(project.edges[selected.id]||{}),color:validColor($('edgeColor').value),note:cleanText($('edgeNote').value)};draw();selectEdge(selected.id,true);};$('clearEdgeColor').onclick=()=>{if(project.edges[selected.id])project.edges[selected.id].color='';draw();selectEdge(selected.id,true);};$('closeNodeInspector').onclick=clearSelection;$('closeEdgeInspector').onclick=clearSelection;
  $('zoomIn').onclick=()=>{zoom=Math.min(2.5,zoom+.15);applyZoom();centerViewport();};$('zoomOut').onclick=()=>{zoom=Math.max(.2,zoom-.15);applyZoom();centerViewport();};$('zoomReset').onclick=()=>{zoom=1;applyZoom();centerViewport();};$('fitDiagram').onclick=fitDiagram;$('exportButton').onclick=()=>$('exportDialog').showModal();$('exportSvg').onclick=()=>{try{download(safeFile('svg'),new Blob([createExportSvg()],{type:'image/svg+xml;charset=utf-8'}));}catch(error){toast(error.message);}};$('exportPng').onclick=exportPng;$('exportPdfReport').onclick=openPrintReport;$('expandChains').onclick=()=>{const cards=[...document.querySelectorAll('.chain-card')],open=cards.some(card=>!card.open);cards.forEach(card=>card.open=open);};$('graph').addEventListener('click',event=>{if(event.target===$('graph')||event.target.classList.contains('export-background'))clearSelection();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('exportDialog').open)clearSelection();});document.addEventListener('click',event=>{if(!event.target.closest('.project-tools')){$('projectMenu').classList.add('hidden');$('projectMenuButton').setAttribute('aria-expanded','false');}});window.addEventListener('beforeunload',event=>{if(saveRevision>savedRevision||saveState==='saving'||saveState==='failed'){event.preventDefault();event.returnValue='';}});
}
function renderGuided(){$('guidedTokens').innerHTML=guided.map((name,index)=>`<span class="token">${ar(index+1)}. ${esc(name)}</span>`).join('');}

async function projectAction(action){$('projectMenu').classList.add('hidden');if(!action)return;if(action==='new'){await saveProject(false);const name=prompt('اسم المشروع الجديد:','مشروع جديد');if(name===null)return;project=freshProject(cleanText(name,200)||'مشروع جديد');resetSaveTracking();await saveProject(false);applyProject();}if(action==='rename'){const name=prompt('الاسم الجديد:',project.name);if(name?.trim()){project.name=cleanText(name,200);await saveProject();}}if(action==='duplicate'){await saveProject(false);const copy=structuredClone(project),now=new Date().toISOString();copy.id=uid('project');copy.name=`${copy.name} — نسخة`;copy.createdAt=now;copy.updatedAt=now;project=copy;resetSaveTracking();await saveProject();applyProject();}if(action==='export-json')download(`${project.name.replace(/[\\/:*?"<>|]/g,'-')}.json`,new Blob([JSON.stringify(project,null,2)],{type:'application/json'}));if(action==='import-json')$('jsonFile').click();if(action==='delete'){const all=await dbAll();if(all.length===1)return toast('يجب إبقاء مشروع واحد على الأقل.');if(confirm(`حذف «${project.name}» من هذا الجهاز؟`)){await dbDelete(project.id);const remaining=(await dbAll()).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));project=migrateProject(remaining[0]);applyProject();await refreshProjectSelect();}}}
async function importProject(event){try{const file=event.target.files?.[0];if(!file)return;if(file.size>LIMITS.file)throw Error('حجم الملف أكبر من الحد المسموح.');await saveProject(false);const parsed=JSON.parse(await file.text()),imported=sanitizeProject(parsed,false);assertAcyclic(imported);imported.id=uid('project');imported.name=`${imported.name||'مشروع مستورد'} — مستورد`;imported.createdAt=new Date().toISOString();imported.updatedAt=new Date().toISOString();project=imported;resetSaveTracking();await saveProject();applyProject();toast('تم استيراد المشروع كاملًا بعد التحقق من بنيته.');}catch(error){setSaveStatus('failed');alert(`تعذر الاستيراد: ${error.message}`);}finally{event.target.value='';}}

function sanitizeProject(raw,preserveId=true){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('بنية الملف غير صالحة.');if(typeof raw.chains==='string')return migrateLegacyProject(raw,preserveId);if(!Array.isArray(raw.chains)||raw.chains.length>LIMITS.chains)throw Error('قائمة الأسانيد غير صالحة أو كبيرة جدًا.');
  const clean=freshProject(cleanText(raw.name||'مشروع مستورد',200));clean.id=preserveId&&typeof raw.id==='string'?cleanText(raw.id,160):uid('project');clean.title=cleanText(raw.title||'مشجّر حديث',300);clean.matn=cleanText(raw.matn||'',LIMITS.text);clean.researcher=cleanText(raw.researcher||'',LIMITS.name);clean.researchNotes=cleanText(raw.researchNotes||'',LIMITS.text);clean.createdAt=typeof raw.createdAt==='string'?raw.createdAt:new Date().toISOString();clean.updatedAt=typeof raw.updatedAt==='string'?raw.updatedAt:new Date().toISOString();clean.settings={mergeExact:!!raw.settings?.mergeExact,colorMode:raw.settings?.colorMode==='chain'?'chain':'branch',showLegend:raw.settings?.showLegend!==false,showMatn:raw.settings?.showMatn!==false};
  const idMap=new Map(),oldNodes=raw.nodes&&typeof raw.nodes==='object'&&!Array.isArray(raw.nodes)?raw.nodes:{};const getIdentity=oldId=>{const key=String(oldId??uid('missing'));if(!idMap.has(key))idMap.set(key,/^n-[a-z0-9-]+$/i.test(key)&&preserveId?key:uid('n'));return idMap.get(key);};
  raw.chains.forEach((chain,chainIndex)=>{if(!chain||typeof chain!=='object'||!Array.isArray(chain.narrators)||chain.narrators.length<2||chain.narrators.length>LIMITS.narrators)throw Error(`الإسناد ${chainIndex+1} ناقص أو غير صالح.`);const narrators=chain.narrators.map((item,narratorIndex)=>{if(!item||typeof item!=='object')throw Error(`راوٍ غير صالح في الإسناد ${chainIndex+1}.`);const name=cleanText(item.name,LIMITS.name);if(!name)throw Error(`اسم راوٍ فارغ في الإسناد ${chainIndex+1}.`);const oldIdentity=String(item.identityId??`${chainIndex}:${narratorIndex}`),identityId=getIdentity(oldIdentity),rawMeta=own(oldNodes,oldIdentity);if(!clean.nodes[identityId])clean.nodes[identityId]={name:cleanText(rawMeta?.name||name,LIMITS.name),color:validColor(rawMeta?.color),note:cleanText(rawMeta?.note),manualTier:Number.isInteger(rawMeta?.manualTier)&&rawMeta.manualTier>=1&&rawMeta.manualTier<=50?rawMeta.manualTier:null};return{occurrenceId:uid('o'),name,identityId};});const source=chain.source&&typeof chain.source==='object'?chain.source:{};clean.chains.push({id:preserveId&&/^chain-[a-z0-9-]+$/i.test(String(chain.id||''))?String(chain.id):uid('chain'),label:cleanText(chain.label||`الطريق ${chainIndex+1}`,300),narrators,source:{book:cleanText(source.book,1000),volume:cleanText(source.volume,300),page:cleanText(source.page,300),hadith:cleanText(source.hadith,300),free:cleanText(source.free,3000)},note:cleanText(chain.note)});});
  const rawPositions=raw.positions&&typeof raw.positions==='object'?raw.positions:{};idMap.forEach((newId,oldId)=>{const position=own(rawPositions,oldId);if(Number.isFinite(position?.x)&&Number.isFinite(position?.y)&&Math.abs(position.x)<50000&&Math.abs(position.y)<50000)clean.positions[newId]={x:position.x,y:position.y};});const rawEdges=raw.edges&&typeof raw.edges==='object'?raw.edges:{};clean.chains.forEach((chain,chainIndex)=>{const rawChain=raw.chains[chainIndex];for(let index=1;index<chain.narrators.length;index++){const newKey=edgeKey(chain.narrators[index-1].identityId,chain.narrators[index].identityId),oldKey=edgeKey(rawChain.narrators[index-1].identityId,rawChain.narrators[index].identityId),meta=own(rawEdges,oldKey);if(meta&&!clean.edges[newKey])clean.edges[newKey]={color:validColor(meta.color),note:cleanText(meta.note)};}});clean.projectNotes=Array.isArray(raw.projectNotes)?raw.projectNotes.slice(0,500).filter(note=>note&&typeof note==='object'&&cleanText(note.text)).map(note=>({id:uid('note'),text:cleanText(note.text)})):[];return clean;
}
function migrateLegacyProject(raw,preserveId){const migrated=freshProject(cleanText(raw.name||'مشروع قديم',200));migrated.id=preserveId&&typeof raw.id==='string'?cleanText(raw.id,160):uid('project');migrated.title=cleanText(raw.title||'مشجّر حديث',300);migrated.researcher=cleanText(raw.researcher||'',LIMITS.name);migrated.researchNotes=cleanText(raw.researchNotes||'',LIMITS.text);migrated.settings.mergeExact=true;const lines=String(raw.chains||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean),sources=String(raw.sources||'').split(/\r?\n/),identities=new Map();lines.forEach((line,chainIndex)=>{const names=line.split(/[,،]/).map(name=>name.trim()).filter(Boolean);if(names.length<2)return;const narrators=names.map(name=>{const key=normalize(name);if(!identities.has(key))identities.set(key,uid('n'));const identityId=identities.get(key);migrated.nodes[identityId]||={name,color:validColor(raw.colors?.[name]),note:cleanText(raw.notes?.[name]),manualTier:null};const position=raw.positions?.[name];if(Number.isFinite(position?.x)&&Number.isFinite(position?.y))migrated.positions[identityId]={x:position.x,y:position.y};return{occurrenceId:uid('o'),name,identityId};});migrated.chains.push({id:uid('chain'),label:`الطريق ${chainIndex+1}`,narrators,source:{book:'',volume:'',page:'',hadith:'',free:cleanText(sources[chainIndex])},note:''});});migrated.projectNotes=String(raw.generalNotes||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(text=>({id:uid('note'),text:cleanText(text)}));return migrated;}
function migrateProject(raw){try{return sanitizeProject(raw,true);}catch(error){console.error('تعذر ترحيل المشروع',error);return raw;}}
function assertAcyclic(value){const indegree=new Map(),outgoing=new Map();value.chains.forEach(chain=>chain.narrators.forEach(item=>{indegree.set(item.identityId,indegree.get(item.identityId)||0);outgoing.set(item.identityId,outgoing.get(item.identityId)||new Set());}));value.chains.forEach(chain=>{for(let index=1;index<chain.narrators.length;index++){const from=chain.narrators[index-1].identityId,to=chain.narrators[index].identityId;if(from===to)throw Error('يحتوي الملف على هوية مكررة متتابعة.');if(!outgoing.get(from).has(to)){outgoing.get(from).add(to);indegree.set(to,indegree.get(to)+1);}}});const queue=[...indegree].filter(([,count])=>count===0).map(([id])=>id);let visited=0;while(queue.length){const id=queue.shift();visited++;outgoing.get(id).forEach(to=>{indegree.set(to,indegree.get(to)-1);if(indegree.get(to)===0)queue.push(to);});}if(visited!==indegree.size)throw Error('يحتوي الملف على دورة في علاقات الرواية.');}

function mergeSelected(){const target=$('mergeTarget').value,source=selected.id;if(!target)return toast('اختر الهوية المراد الجمع معها.');const backup=structuredClone(project);project.chains.forEach(chain=>chain.narrators.forEach(item=>{if(item.identityId===source)item.identityId=target;}));const sourceMeta=nodeMeta(source),targetMeta=nodeMeta(target);if(sourceMeta.note&&!targetMeta.note)targetMeta.note=sourceMeta.note;delete project.nodes[source];delete project.positions[source];selected={type:'node',id:target};try{assertAcyclic(project);prune();draw();selectNode(target,true);toast('جُمعت الهويتان مع بقاء جميع سجلات الطرق.');}catch(error){project=backup;selected={type:'node',id:source};draw();selectNode(source,true);toast(error.message);}}
function splitSelected(){const occurrenceId=$('splitOccurrence').value;if(!occurrenceId)return;const old=nodeMeta(selected.id),id=uid('n');project.nodes[id]={...structuredClone(old),name:old.name,color:'',manualTier:null};for(const chain of project.chains){const occurrence=chain.narrators.find(item=>item.occurrenceId===occurrenceId);if(occurrence){occurrence.identityId=id;break;}}selected={type:'node',id};project.positions={};draw();selectNode(id,true);toast('فُصل هذا الظهور في هوية مستقلة.');}
function applyZoom(){const svg=$('graph'),width=Number(svg.getAttribute('width'))||0,height=Number(svg.getAttribute('height'))||0;svg.style.transform='none';svg.style.width=width?`${width*zoom}px`:'';svg.style.height=height?`${height*zoom}px`:'';$('zoomReset').textContent=`${ar(Math.round(zoom*100))}٪`;}
function centerViewport(behavior='auto'){const svg=$('graph'),viewport=$('diagramViewport');requestAnimationFrame(()=>viewport.scrollTo({top:0,left:Math.max(0,(svg.getBoundingClientRect().width-viewport.clientWidth)/2),behavior}));}
function fitDiagram(){const svg=$('graph'),viewport=$('diagramViewport');if(!svg.viewBox.baseVal.width)return;zoom=Math.max(.2,Math.min(1.2,(viewport.clientWidth-30)/svg.viewBox.baseVal.width,(viewport.clientHeight-30)/svg.viewBox.baseVal.height));applyZoom();centerViewport('smooth');}
async function exportPng(){try{await document.fonts.ready;const source=createExportSvg(),url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml;charset=utf-8'})),image=new Image();image.onload=()=>{const ratio=image.naturalWidth/image.naturalHeight,canvas=document.createElement('canvas');canvas.width=Math.min(12000,Math.max(1600,image.naturalWidth*3));canvas.height=Math.round(canvas.width/ratio);const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>blob?download(safeFile('png'),blob):toast('تعذر إنشاء PNG.'),'image/png');URL.revokeObjectURL(url);};image.onerror=()=>{URL.revokeObjectURL(url);toast('تعذر إنشاء PNG؛ جرّب SVG.');};image.src=url;}catch(error){toast(error.message);}}

async function init(){bind();await openDB();try{await document.fonts.ready;}catch(error){console.warn('تعذر انتظار الخط؛ سيُستخدم الخط الاحتياطي.',error);}const all=await dbAll();if(!all.length){project=demoProject();await dbPut(project);}else{let lastId='';try{lastId=localStorage.getItem('lastIsnadProject')||'';}catch{}project=migrateProject(all.find(item=>item.id===lastId)||all[0]);await dbPut(project);}await refreshProjectSelect();applyProject();setTimeout(fitDiagram,120);}
init().catch(error=>{console.error(error);alert(`تعذر تشغيل التخزين المحلي: ${error.message}`);});
